diff --git a/repro/check.js b/repro/check.js
new file mode 100644
index 000000000..59384910e
--- /dev/null
+++ b/repro/check.js
@@ -0,0 +1,47 @@
+// Check for the report: "Type assertion regression in TypeScript 5.7".
+//
+// Usage (from the repo root):
+//   node repro/check.js [path/to/typescript.js] [file.ts]
+// Defaults: the locally built compiler (built/local/typescript.js) and repro/issue.ts
+// (the code from the report, unchanged).
+//
+// Asserts the expected behavior from the report: the type of `Test` is displayed
+// (quickinfo / hover, as in the Playground) as `{ prop1: "hello"; }`.
+// Exits 0 if it is, 1 if it is not.
+const fs = require("fs");
+const path = require("path");
+const tsPath = path.resolve(process.argv[2] || path.join(__dirname, "..", "built", "local", "typescript.js"));
+const file = path.resolve(process.argv[3] || path.join(__dirname, "issue.ts"));
+const ts = require(tsPath);
+
+const text = fs.readFileSync(file, "utf8");
+const opts = { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [], skipLibCheck: true };
+const host = {
+    getScriptFileNames: () => [file],
+    getScriptVersion: () => "1",
+    getScriptSnapshot: f => fs.existsSync(f) ? ts.ScriptSnapshot.fromString(fs.readFileSync(f, "utf8")) : undefined,
+    getCurrentDirectory: () => path.dirname(file),
+    getCompilationSettings: () => opts,
+    getDefaultLibFileName: o => ts.getDefaultLibFilePath(o),
+    fileExists: ts.sys.fileExists,
+    readFile: ts.sys.readFile,
+    readDirectory: ts.sys.readDirectory,
+    directoryExists: ts.sys.directoryExists,
+    getDirectories: ts.sys.getDirectories,
+};
+const ls = ts.createLanguageService(host, ts.createDocumentRegistry());
+
+const marker = "type Test";
+const pos = text.indexOf(marker) + marker.length - 1; // on the name `Test`
+const info = ls.getQuickInfoAtPosition(file, pos);
+const actual = (info ? ts.displayPartsToString(info.displayParts) : "<no quickinfo>").replace(/\s+/g, " ").trim();
+const expected = 'type Test = { prop1: "hello"; }';
+
+console.log(`typescript ${ts.version}  (${file})`);
+console.log(`expected: ${expected}`);
+console.log(`actual:   ${actual}`);
+if (actual !== expected) {
+    console.error("FAIL: the displayed type of `Test` is not the expected one");
+    process.exit(1);
+}
+console.log("PASS");
diff --git a/repro/inspect.js b/repro/inspect.js
new file mode 100644
index 000000000..89a2a531f
--- /dev/null
+++ b/repro/inspect.js
@@ -0,0 +1,16 @@
+// Supporting evidence (not the check): in the reported code the checker's *type* of
+// Test.prop1 is already the string literal "hello" (so assignability etc. behave as in 5.6);
+// only the *printed* form of the type is wrong.
+// Usage: node repro/inspect.js [path/to/typescript.js] [file.ts]
+const path = require("path");
+const ts = require(path.resolve(process.argv[2] || path.join(__dirname, "..", "built", "local", "typescript.js")));
+const file = path.resolve(process.argv[3] || path.join(__dirname, "issue.ts"));
+const program = ts.createProgram([file], { strict: true, noEmit: true, target: ts.ScriptTarget.ES2022, types: [], skipLibCheck: true });
+const checker = program.getTypeChecker();
+let decl;
+(function v(n) { if (ts.isTypeAliasDeclaration(n) && n.name.text === "Test") decl = n; ts.forEachChild(n, v); })(program.getSourceFile(file));
+const T = checker.getTypeAtLocation(decl.name);
+const prop = checker.getTypeOfSymbol(T.getProperty("prop1"));
+console.log("typescript", ts.version);
+console.log("typeToString(Test):      ", checker.typeToString(T, undefined, ts.TypeFormatFlags.NoTruncation));
+console.log("typeToString(Test.prop1):", checker.typeToString(prop), "| is string literal:", !!(prop.flags & ts.TypeFlags.StringLiteral));
diff --git a/repro/issue.ts b/repro/issue.ts
new file mode 100644
index 000000000..7c28a519a
--- /dev/null
+++ b/repro/issue.ts
@@ -0,0 +1,21 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
